#include "CinemaSourceDomainStream.h"
#include "SourceCycleTimer.h"
#include "ProAudioThreadScope.h"
#include <iostream>
#include <fstream>
#include <array>
#include <chrono>
using namespace entropy::host;
int main(int argc,char**argv){std::string error;auto root=std::filesystem::path(TEST_MODULE_ROOT);auto el=ModuleLibrary::load(root/"EntropyCinemaInput.dll",error),sl=ModuleLibrary::load(root/"EntropySampleRateConverter.dll",error);if(!el||!sl){std::cerr<<error;return 2;}ModuleInstance ep(el),src(sl);if(!ep.create(error)||!src.create(error)||!ep.prepare(192000,1024,0,8,error)||!src.prepare(192000,1024,8,8,error))return 2;SourceDomainConfig cfg;cfg.channels=8;cfg.srcEngine=2;cfg.endpointReadFrames=1024;cfg.fifoCapacityFrames=524288;cfg.captureFifoCapacityFrames=131072;cfg.prerollFrames=8192;cfg.outputTargetFrames=16384;CinemaSourceDomainStream s;if(!s.prepare(ep,src,cfg)||!s.start())return 2;std::ofstream f(argc>1?argv[1]:"cinema-live.csv");f<<"seconds,source_rate,endpoint_available,capture_fill,converted_fill,input_frames,output_frames,src_latency_output_samples,faults,missing,peak\n";auto begin=std::chrono::steady_clock::now();while(!s.ready()&&std::chrono::steady_clock::now()-begin<std::chrono::seconds(5))Sleep(1);if(!s.ready()){s.stop();return 3;}std::array<std::array<double,1024>,8>b{};std::array<double*,8>p{};for(unsigned c=0;c<8;++c)p[c]=b[c].data();SourceCycleTimer timer;ProAudioThreadScope realtime;unsigned missing=0;auto epoch=std::chrono::steady_clock::now();if(argc>2){Sleep(2000);epoch=std::chrono::steady_clock::now();}for(unsigned n=0;n<30*192000/1024;++n){timer.waitUntil(epoch+std::chrono::nanoseconds(uint64_t(n)*1024*1000000000/192000));SourceStreamDescriptor d;if(!s.pop1024(p.data(),d))++missing;if(n%188==0){auto t=s.telemetry();f<<std::chrono::duration<double>(std::chrono::steady_clock::now()-epoch).count()<<','<<t.source_rate<<','<<t.endpoint_available_frames<<','<<t.capture_fifo.fill_frames<<','<<t.fifo.fill_frames<<','<<t.src_input_frames<<','<<t.src_output_frames<<','<<t.src_latency_frames<<','<<t.faults<<','<<missing<<','<<t.peak_left<<'\n';}}s.stop();std::cout<<"LIVE probe complete missing="<<missing<<" (independent reader; existing production process unchanged)\n";}
